"""C3.3A3 source-locked derivative; baseline generator and verifier are unchanged."""
import hashlib,sys
from pathlib import Path
base=Path(__file__).resolve().parent
if len(sys.argv)>1 and sys.argv[1]=="--verify":
    p=base/"verify-library-refined.py"
    raw=p.read_bytes()
    assert hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\x00"+raw).hexdigest()=="1897df8b371c13973096b722d77f40ac2d59e323"
    sys.argv=[sys.argv[0],sys.argv[2]]
    code="\"\"\"C3.3A3 acceptance: shell + linked bay placement contract, not browser qualification.\"\"\"\nimport pathlib,sys,hashlib,math,json,struct\np=pathlib.Path(sys.argv[1]);m=json.loads((p/\"library-manifest.json\").read_text())\nassert m[\"phase\"]==\"C3.3A3\" and m[\"studentAuthorized\"] is False and m[\"portalsIntegrated\"] is False\nassert m[\"levels\"]==3 and m[\"sectors\"]==18 and m[\"openSectors\"]==[0,1,17] and m[\"sharedBayMeshCount\"]==25 and m[\"bookVariants\"]==3 and m[\"variantGLBsProduced\"] is False\nassert m[\"bayCount\"]==45 and len(m[\"placements\"])==45\nassert {(q[\"sector\"],q[\"level\"]) for q in m[\"placements\"]}=={(i,j) for i in range(2,17) for j in range(3)}\nfor q in m[\"placements\"]:\n    x,y,z=q[\"positionBlender\"];t=2*math.pi*q[\"sector\"]/18\n    assert math.isclose(x,10.6*math.sin(t),abs_tol=1e-5) and math.isclose(y,10.6*math.cos(t),abs_tol=1e-5)\n    assert math.isclose(z,q[\"level\"]*3.63,abs_tol=1e-5) and math.isclose(q[\"rotationZ\"],-t)\n    assert q[\"detailVariant\"]==(q[\"sector\"]*2+q[\"level\"])%3\nao=p.parent/\"atlas-c32b\"/\"campata-ao.glb\";assert hashlib.sha256(ao.read_bytes()).hexdigest()==m[\"qualifiedBayGlbSha256\"]\nassert hashlib.sha256((p.parent/\"atlas-c32\"/\"campata.blend\").read_bytes()).hexdigest()==m[\"sourceBlendSha256\"]\nfor name,item in m[\"files\"].items():\n    b=(p/name).read_bytes();assert len(b)==item[\"bytes\"] and hashlib.sha256(b).hexdigest()==item[\"sha256\"],name\nfor name,dimensions in ((\"atrium.png\",(1200,750)),(\"vertical.png\",(640,960)),(\"detail.png\",(900,700))):\n    b=(p/name).read_bytes();assert b.startswith(b\"\\x89PNG\\r\\n\\x1a\\n\") and struct.unpack_from(\">II\",b,16)==dimensions and len(b)>30000,name\nb=(p/\"library-shell.glb\").read_bytes();assert struct.unpack_from(\"<4sII\",b)==(b\"glTF\",2,len(b))\nn,t=struct.unpack_from(\"<I4s\",b,12);assert t==b\"JSON\";d=json.loads(b[20:20+n])\nassert d[\"asset\"][\"version\"]==\"2.0\" and not d.get(\"extensionsRequired\")\nassert all(\"uri\" not in item for k in (\"buffers\",\"images\") for item in d.get(k,[]))\nprimitives=sum(len(q[\"primitives\"]) for q in d[\"meshes\"])\nassert 1<=primitives<=18 and len(b)<=12*1024*1024,(primitives,len(b))\nassert m[\"skyProjection\"]==\"EQUIRECTANGULAR\" and m[\"skyVector\"]==\"native-world-Z-up\" and m[\"archThickness\"]==.90 and m[\"artisticApproval\"] is False\nassert m[\"skySha256\"]==\"cf7220b7d6705577e772c28a75cfd67ef508b342904e24d20f227a38fe853130\"\nassert hashlib.sha256((p.parent/\"atlas-c32/assets/kloppenheim_03.hdr\").read_bytes()).hexdigest()==m[\"skySha256\"]\nassert len({q[\"detailVariant\"] for q in m[\"placements\"]})==3\nassert all(\"Library bay \" not in q.get(\"name\",\"\") for q in d[\"nodes\"])\nreceipt={\"status\":\"PASS\",\"phase\":\"C3.3A3\",\"bayPlacements\":45,\"sharedBayMeshes\":25,\"bookVariants\":3,\"shellPrimitives\":primitives,\"shellBytes\":len(b),\"bayBytes\":ao.stat().st_size,\"variantGLBsProduced\":False,\"renders\":3,\"browserQualified\":False,\"studentAuthorized\":False}\n(p/\"library-verification.json\").write_text(json.dumps(receipt,indent=2)+\"\\n\");print(json.dumps(receipt,indent=2))\n"
else:
    p=base/"library-refined.py"
    raw=p.read_bytes()
    assert hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\x00"+raw).hexdigest()=="d94f826f5496ec5991743375de3e1c49d50cdec5"
    code=raw.decode("utf-8")
    edits=[["\"\"\"C3.3A2: refined offline architecture derived from preserved C3.3A.\"\"\"","\"\"\"C3.3A3: art-directed offline architecture, derived from preserved C3.3A2.\"\"\""],["p.inputs[\"Roughness\"].default_value=.20","p.inputs[\"Roughness\"].default_value=.27"],["warm=material(\"Warm luminous brass\",(.95,.58,.25),.32,0,3.0)","warm=material(\"Warm luminous brass\",(.95,.69,.40),.38,0,1.7)"],["65,(1,.76,.49),1.45","48,(1,.85,.67),1.65"],["ring(\"Crown upper coping\",9.12,11.70,11.38,11.52,stone)","ring(\"Crown upper coping\",9.12,11.70,11.38,11.52,stone)\nring(\"Crown inner moulding\",9.08,9.27,10.68,10.79,stone)\nring(\"Crown upper moulding\",9.06,9.24,11.31,11.43,stone)"],["arch_y=10.0;spring=4.0;radius=4.35;thickness=.62","arch_y=10.0;spring=4.0;radius=4.35;thickness=.90"],["    mesh(\"Arch voussoir\",v,[(3,2,1,0),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)],stone,shell)","    faces=[(3,2,1,0),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)]\n    mesh(\"Arch voussoir\",v,faces,stone,shell)\n    outer=radius+thickness\n    # Spandrel follows the outer arch curve and ties into the lintel, without filling its opening.\n    v=[(x,arch_y+dy,z) for dy in (-.60,.60) for x,z in ((outer*cos(a),spring+outer*sin(a)),(outer*cos(b),spring+outer*sin(b)),(outer*cos(b),9.48),(outer*cos(a),9.48))]\n    mesh(\"Arch spandrel\",v,faces,stone,shell)\n    # Narrow projecting stone archivolt on the interior face.\n    v=[(r*cos(t),arch_y+dy,spring+r*sin(t)) for dy in (-.76,-.60) for r,t in ((radius,a),(radius+.20,a),(radius+.20,b),(radius,b))]\n    mesh(\"Arch moulding\",v,faces,stone,shell)"],["for t in (-math.radians(36),math.radians(36)):","for t in (0.0,):"],["coords=nodes.new(\"ShaderNodeTexCoord\");mapping=nodes.new(\"ShaderNodeMapping\");mapping.inputs[\"Rotation\"].default_value[2]=math.radians(110)\nlinks.new(coords.outputs[\"Normal\"],mapping.inputs[\"Vector\"]);links.new(mapping.outputs[\"Vector\"],env.inputs[\"Vector\"])","# Native world direction: Blender Environment Texture maps +Z up when Vector is unconnected.\nenv.projection=\"EQUIRECTANGULAR\"\nassert not env.inputs[\"Vector\"].is_linked"],["light.inputs[\"Strength\"].default_value=.38","light.inputs[\"Strength\"].default_value=.32"],["visible.inputs[\"Strength\"].default_value=.80","visible.inputs[\"Strength\"].default_value=.95"],["area(\"Diffuse skylight\",(0,-1,10.5),(0,0,0),2100,(1,.94,.85),8.0)","area(\"Diffuse skylight\",(0,-1,12.8),(0,0,0),2500,(.86,.93,1),8.0)"],["area(\"Warm frontal fill\",(0,-7,5),(0,5,3),420,(1,.86,.70),5)","area(\"Warm frontal fill\",(0,-7,5),(0,5,3),270,(1,.91,.82),5)"],["scene.cycles.samples=32","scene.cycles.samples=48"],["\"phase\":\"C3.3A2\"","\"phase\":\"C3.3A3\""],["\"skySource\":\"Poly Haven kloppenheim_03 locked HDRI\"","\"skySource\":\"Poly Haven kloppenheim_03 locked HDRI\",\"skyProjection\":\"EQUIRECTANGULAR\",\"skyVector\":\"native-world-Z-up\",\"archThickness\":thickness,\"artisticApproval\":False"]]
    for old,new in edits:
        assert code.count(old)==1,old
        code=code.replace(old,new,1)
exec(compile(code,str(p),"exec"),globals())
